1: //! The [`Runner`] trait and its carrier types.
2: //!
3: //! The runner is the durability seam (per ADR-6): swappable between
4: //! ephemeral tokio (`paigasus-helikon-runtime-tokio`), durable Temporal
5: //! (`paigasus-helikon-runtime-temporal`), and AWS AgentCore
6: //! (`paigasus-helikon-runtime-agentcore`).
7: 
8: use std::num::NonZeroUsize;
9: use std::time::Duration;
10: 
11: use async_trait::async_trait;
12: 
13: use crate::{
14:     Agent, AgentError, AgentEvent, AgentInput, ContentPart, FailureSlot, Item, RunContext,
15: };
16: 
17: /// Pluggable execution backend.
18: ///
19: /// `Runner` is object-safe: all methods accept `&dyn Agent<Ctx>` rather
20: /// than a generic `<A: Agent<Ctx>>` parameter, which keeps the trait
21: /// vtable-friendly while remaining compatible with both concrete and
22: /// trait-object agent references.
23: ///
24: /// See ADR-6 (*Library + pluggable Runner trait*).
25: ///
26: /// # Example
27: ///
28: /// ```
29: /// use async_trait::async_trait;
30: /// use futures_core::stream::BoxStream;
31: /// use futures_util::stream::empty;
32: /// use paigasus_helikon_core::{
33: ///     Agent, AgentEvent, AgentInput, RunConfig, RunContext, RunError,
34: ///     RunResult, RunResultStreaming, Runner,
35: /// };
36: ///
37: /// struct NoopRunner;
38: ///
39: /// #[async_trait]
40: /// impl Runner<()> for NoopRunner {
41: ///     async fn run(
42: ///         &self,
43: ///         _agent: &(dyn Agent<()> + '_),
44: ///         _ctx: RunContext<()>,
45: ///         _input: AgentInput,
46: ///         _config: RunConfig,
47: ///     ) -> Result<RunResult, RunError> {
48: ///         Ok(RunResult::default())
49: ///     }
50: ///
51: ///     async fn run_streamed(
52: ///         &self,
53: ///         _agent: &(dyn Agent<()> + '_),
54: ///         _ctx: RunContext<()>,
55: ///         _input: AgentInput,
56: ///         _config: RunConfig,
57: ///     ) -> Result<RunResultStreaming, RunError> {
58: ///         let stream: BoxStream<'static, AgentEvent> = Box::pin(empty());
59: ///         Ok(RunResultStreaming::new(stream))
60: ///     }
61: /// }
62: /// ```
63: #[async_trait]
64: pub trait Runner<Ctx>: Send + Sync
65: where
66:     Ctx: Send + Sync + 'static,
67: {
68:     /// Run the agent to completion and return the aggregated result.
69:     ///
70:     /// **With a `Session`** (always present on [`RunContext`]): the runner loads
71:     /// persisted history at start and seeds the conversation as
72:     /// `history ++ input.messages`, so `input` is the *new turn* — the session
73:     /// owns history. The run's events are persisted at exit. To continue with no
74:     /// new turn (or to retry a failed run without re-appending the user message),
75:     /// use [`Runner::resume`].
76:     ///
77:     /// **The returned future must be polled to completion for the run's events to
78:     /// be persisted.** Finalization happens inside this future, so — as with any
79:     /// future — dropping it early cancels the work still in flight, including the
80:     /// session write, and the turn is lost. A caller that cannot guarantee it will
81:     /// poll to completion (an HTTP handler whose client may disconnect, say) should
82:     /// drive the run on a detached task and await its result over a channel, rather
83:     /// than awaiting it inline.
84:     ///
85:     /// **Conversely, this future issues the session write before it resolves**, so
86:     /// callers may treat its resolution as an ordering barrier: the finalize step is
87:     /// ordered before `run` returns, not left in flight behind it. This is what makes
88:     /// "detach and await the result over a channel" a sufficient remedy for the hazard
89:     /// above. Note this is an ordering guarantee, not a durability one: persistence is
90:     /// best-effort, so an implementation may log rather than propagate an append
91:     /// failure, and a run that fails before the agent starts never reaches finalize at
92:     /// all.
93:     ///
94:     /// **Cancellation/timeout is best-effort and loses to a genuine terminal
95:     /// event that already occurred.** If the run reaches a terminal
96:     /// (`RunCompleted`/`RunFailed`) before — or in the same poll as — a cancel or
97:     /// timeout, the runner reports that real outcome (`Ok`, or the structured
98:     /// `Err(RunError::Agent(..))`), not `Err(RunError::Cancelled)` /
99:     /// `Err(RunError::Timeout)`. The cancel/timeout wins only when it aborted the
100:     /// run in-flight, before any terminal event. A caller therefore cannot assume
101:     /// "I called `cancel()` ⇒ I get `Cancelled`".
102:     /// Implementors must apply this rule via [`effective_interrupt`] rather
103:     /// than re-deriving it; [`RunInterrupt`] names the two boundary interrupts.
104:     async fn run(
105:         &self,
106:         agent: &(dyn Agent<Ctx> + '_),
107:         ctx: RunContext<Ctx>,
108:         input: AgentInput,
109:         config: RunConfig,
110:     ) -> Result<RunResult, RunError>;
111: 
112:     /// Run the agent and return a streaming result handle.
113:     ///
114:     /// Session loading/seeding matches [`Runner::run`]. **The returned stream
115:     /// must be driven to its terminal for the run's events to be persisted:** a
116:     /// consumer that drops the stream early may skip the finalize step and leave
117:     /// a partial turn (or nothing) written.
118:     ///
119:     /// The same cancellation precedence as [`Runner::run`] applies: once a real
120:     /// terminal event has been yielded, a late cancel/timeout does not append a
121:     /// second, synthetic terminal — the stream ends after the real one.
122:     /// Gate the synthetic terminal on [`effective_interrupt`], and build it with
123:     /// [`RunInterrupt::terminal_event`] rather than assembling the frame by hand.
124:     async fn run_streamed(
125:         &self,
126:         agent: &(dyn Agent<Ctx> + '_),
127:         ctx: RunContext<Ctx>,
128:         input: AgentInput,
129:         config: RunConfig,
130:     ) -> Result<RunResultStreaming, RunError>;
131: 
132:     /// Resume a run from the session's persisted history with no new input.
133:     ///
134:     /// Equivalent to [`Runner::run`] with an empty [`AgentInput`]: the runner
135:     /// loads the conversation from `ctx.session()` and continues it. Use this to
136:     /// continue a multi-turn session, or to retry a failed run without
137:     /// re-appending the previous turn's user message. (With a `Session` present,
138:     /// [`Runner::run`]'s `input` is the *new turn*; the session owns history.)
139:     async fn resume(
140:         &self,
141:         agent: &(dyn Agent<Ctx> + '_),
142:         ctx: RunContext<Ctx>,
143:         config: RunConfig,
144:     ) -> Result<RunResult, RunError> {
145:         self.run(agent, ctx, AgentInput::new(), config).await
146:     }
147: 
148:     /// Streaming counterpart of [`Runner::resume`]: resumes from session
149:     /// history with no new input and returns a streaming result handle instead
150:     /// of an aggregated [`RunResult`].
151:     async fn resume_streamed(
152:         &self,
153:         agent: &(dyn Agent<Ctx> + '_),
154:         ctx: RunContext<Ctx>,
155:         config: RunConfig,
156:     ) -> Result<RunResultStreaming, RunError> {
157:         self.run_streamed(agent, ctx, AgentInput::new(), config)
158:             .await
159:     }
160: }
161: 
162: /// Per-run configuration.
163: ///
164: /// SMA-314 shipped `max_turns`; SMA-321 added `timeout` and
165: /// `parallel_tool_call_limit`. Cancellation is intentionally *not* a field
166: /// here — the canonical token lives on [`crate::RunContext`].
167: #[derive(Debug, Clone)]
168: #[non_exhaustive]
169: pub struct RunConfig {
170:     /// `[driver-scoped]` Maximum number of model turns before the loop fails
171:     /// with [`crate::AgentError::MaxTurnsExceeded`]. Honored by the core loop
172:     /// driver, including on a bare `agent.run()` with no runner. Default `16`.
173:     pub max_turns: u32,
174:     /// `[runner-scoped]` Wall-clock deadline for the whole run. Honored ONLY by
175:     /// a runtime backend (e.g. `TokioRunner`); a bare `agent.run()` cannot time
176:     /// out (core has no timer). `None` = no deadline.
177:     pub timeout: Option<Duration>,
178:     /// `[driver-scoped]` Cap on concurrently-executing tool calls. Honored by
179:     /// the core loop driver. `None` = unbounded (today's behavior).
180:     pub parallel_tool_call_limit: Option<NonZeroUsize>,
181:     /// `[driver-scoped]` Maximum agent-nesting depth across **both** handoff
182:     /// chains and `AgentAsTool` sub-runs. Each nested agent run increments the
183:     /// depth; exceeding this fails with
184:     /// [`crate::AgentError::MaxAgentDepthExceeded`]. Default `8`.
185:     pub max_agent_depth: u32,
186: }
187: 
188: impl Default for RunConfig {
189:     fn default() -> Self {
190:         Self {
191:             max_turns: 16,
192:             timeout: None,
193:             parallel_tool_call_limit: None,
194:             max_agent_depth: 8,
195:         }
196:     }
197: }
198: 
199: impl RunConfig {
200:     /// Construct a default config (`max_turns = 16`).
201:     pub fn new() -> Self {
202:         Self::default()
203:     }
204: 
205:     /// Set the wall-clock run deadline. Honored by a runtime backend (e.g. `TokioRunner`).
206:     pub fn with_timeout(mut self, timeout: Duration) -> Self {
207:         self.timeout = Some(timeout);
208:         self
209:     }
210: 
211:     /// Cap the number of tool calls executed concurrently. Honored by the core loop driver.
212:     pub fn with_parallel_tool_call_limit(mut self, limit: NonZeroUsize) -> Self {
213:         self.parallel_tool_call_limit = Some(limit);
214:         self
215:     }
216: 
217:     /// Set the maximum agent-nesting depth (handoff + agent-as-tool). Honored by the core loop driver.
218:     pub fn with_max_agent_depth(mut self, depth: u32) -> Self {
219:         self.max_agent_depth = depth;
220:         self
221:     }
222: }
223: 
224: /// The aggregated outcome of a non-streaming [`Runner::run`].
225: ///
226: /// Generic over the structured-output type. The default `T = String`
227: /// makes the common case ergonomic; structured-output callers build
228: /// `RunResult<MyStruct>` via [`RunResult::parse_final`].
229: #[derive(Debug, Default, Clone)]
230: #[non_exhaustive]
231: pub struct RunResult<T = String> {
232:     /// The model's final assistant output, deserialized into `T`. For
233:     /// the default `T = String` this is the literal text.
234:     pub final_output: T,
235:     /// Every [`AgentEvent`] emitted during the run, in order.
236:     pub events: Vec<AgentEvent>,
237:     /// Aggregated token usage across every turn of the run.
238:     pub usage: TokenUsage,
239: }
240: 
241: impl RunResult<String> {
242:     /// Deserialize `final_output` into `T`, producing a typed
243:     /// [`RunResult`].
244:     ///
245:     /// The `T: JsonSchema` bound is the marker that the caller has
246:     /// configured structured output upstream — without it,
247:     /// `parse_final` is just a JSON parse over unstructured text.
248:     pub fn parse_final<T>(self) -> Result<RunResult<T>, serde_json::Error>
249:     where
250:         T: serde::de::DeserializeOwned + schemars::JsonSchema,
251:     {
252:         let final_output = serde_json::from_str::<T>(&self.final_output)?;
253:         Ok(RunResult {
254:             final_output,
255:             events: self.events,
256:             usage: self.usage,
257:         })
258:     }
259: }
260: 
261: /// Streaming counterpart of [`RunResult`].
262: ///
263: /// Wraps the unified [`crate::AgentEvent`] stream emitted by an agent
264: /// and offers an `async fn collect` that drains the stream into a
265: /// `RunResult<String>`. Callers may consume `events` directly for raw
266: /// streaming.
267: pub struct RunResultStreaming {
268:     /// The event stream produced by the agent's run.
269:     pub events: futures_core::stream::BoxStream<'static, crate::AgentEvent>,
270:     /// Side-channel carrying the run's terminal structured [`AgentError`], when
271:     /// a runner wired one in via [`RunResultStreaming::with_failure`]. Read only
272:     /// after the stream is fully drained. `None` for a bare
273:     /// [`RunResultStreaming::new`], in which case `collect` falls back to the
274:     /// string error from [`AgentEvent::RunFailed`].
275:     failure: Option<FailureSlot>,
276: }
277: 
278: impl RunResultStreaming {
279:     /// Wrap an event stream with no structured-error side-channel. `collect`
280:     /// then surfaces failures as the opaque string from `RunFailed`.
281:     pub fn new(events: futures_core::stream::BoxStream<'static, crate::AgentEvent>) -> Self {
282:         Self {
283:             events,
284:             failure: None,
285:         }
286:     }
287: 
288:     /// Wrap an event stream together with the [`FailureSlot`] the agent records
289:     /// its terminal structured [`AgentError`] into, so `collect` /
290:     /// `collect_typed` surface `RunError::Agent` / the real `AgentError` instead
291:     /// of the opaque string.
292:     pub fn with_failure(
293:         events: futures_core::stream::BoxStream<'static, crate::AgentEvent>,
294:         failure: FailureSlot,
295:     ) -> Self {
296:         Self {
297:             events,
298:             failure: Some(failure),
299:         }
300:     }
301: 
302:     /// Drain the stream and aggregate into a `RunResult<String>`.
303:     ///
304:     /// `final_output` is the concatenated text from the *last*
305:     /// `AgentEvent::MessageOutput { item: AssistantMessage }`. In multi-turn
306:     /// flows, each new assistant message resets `final_output`, ensuring
307:     /// the result is the terminal assistant output, not intermediate text.
308:     /// Structured-output callers go through `RunResult::<String>::parse_final::<T>()`
309:     /// (SMA-313).
310:     pub async fn collect(mut self) -> Result<RunResult, RunError> {
311:         use futures_util::stream::StreamExt;
312:         let mut events = Vec::new();
313:         let mut final_output = String::new();
314:         let mut usage = crate::TokenUsage::default();
315:         // Capture the RunFailed string but keep draining: state-machine failures
316:         // record their structured error AFTER yielding RunFailed, so the slot is
317:         // only guaranteed populated once the stream ends.
318:         let mut failed: Option<String> = None;
319: 
320:         while let Some(ev) = self.events.next().await {
321:             match &ev {
322:                 crate::AgentEvent::MessageOutput {
323:                     item: crate::Item::AssistantMessage { content, .. },
324:                 } => {
325:                     final_output.clear();
326:                     for part in content {
327:                         if let crate::ContentPart::Text { text } = part {
328:                             final_output.push_str(text);
329:                         }
330:                     }
331:                 }
332:                 crate::AgentEvent::RunCompleted { usage: u } => usage = *u,
333:                 crate::AgentEvent::RunFailed { error } => {
334:                     failed = Some(error.clone());
335:                 }
336:                 _ => {}
337:             }
338:             events.push(ev);
339:         }
340: 
341:         if let Some(err_msg) = failed {
342:             if let Some(err) = self.failure.as_ref().and_then(FailureSlot::take) {
343:                 return Err(RunError::Agent(err));
344:             }
345:             return Err(RunError::Other(anyhow::anyhow!(err_msg)));
346:         }
347: 
348:         Ok(RunResult {
349:             final_output,
350:             events,
351:             usage,
352:         })
353:     }
354: 
355:     /// Drain the stream and deserialize the terminal assistant text into `T`.
356:     ///
357:     /// The terminal output is the concatenated text of the last
358:     /// [`AgentEvent::MessageOutput`]. On a correctly configured structured run
359:     /// the agent loop has already validated that text against `T`, so the parse
360:     /// here is expected to succeed; if it fails (e.g. `collect_typed` is called
361:     /// on a plain-text run), the parse error surfaces as [`AgentError::Other`].
362:     /// A failed run surfaces the underlying [`AgentError`]:
363:     /// structured-validation failures (carried by
364:     /// [`AgentEvent::StructuredOutputFailed`]) become
365:     /// [`AgentError::InvalidStructuredOutput`]; any other terminal
366:     /// [`AgentEvent::RunFailed`] becomes [`AgentError::Other`].
367:     pub async fn collect_typed<T>(mut self) -> Result<RunResult<T>, AgentError>
368:     where
369:         T: serde::de::DeserializeOwned,
370:     {
371:         use futures_util::stream::StreamExt;
372:         let mut events = Vec::new();
373:         let mut final_text = String::new();
374:         let mut usage = crate::TokenUsage::default();
375:         let mut structured_err: Option<(Vec<String>, String)> = None;
376:         let mut failed: Option<String> = None;
377: 
378:         while let Some(ev) = self.events.next().await {
379:             match &ev {
380:                 AgentEvent::MessageOutput {
381:                     item: Item::AssistantMessage { content, .. },
382:                 } => {
383:                     final_text.clear();
384:                     for part in content {
385:                         if let ContentPart::Text { text } = part {
386:                             final_text.push_str(text);
387:                         }
388:                     }
389:                 }
390:                 AgentEvent::RunCompleted { usage: u } => usage = *u,
391:                 AgentEvent::StructuredOutputFailed {
392:                     schema_errors,
393:                     final_text: ft,
394:                 } => {
395:                     structured_err = Some((schema_errors.clone(), ft.clone()));
396:                 }
397:                 AgentEvent::RunFailed { error } => {
398:                     failed = Some(error.clone());
399:                 }
400:                 _ => {}
401:             }
402:             events.push(ev);
403:         }
404: 
405:         if let Some(err_msg) = failed {
406:             // Primary: the structured side-channel (populated post-drain).
407:             if let Some(err) = self.failure.as_ref().and_then(FailureSlot::take) {
408:                 return Err(err);
409:             }
410:             // Fallback 1: reconstruct InvalidStructuredOutput from its event.
411:             if let Some((schema_errors, final_text)) = structured_err {
412:                 return Err(AgentError::InvalidStructuredOutput {
413:                     schema_errors,
414:                     final_text,
415:                 });
416:             }
417:             // Fallback 2: the opaque string.
418:             return Err(AgentError::Other(anyhow::anyhow!(err_msg)));
419:         }
420: 
421:         let final_output = serde_json::from_str::<T>(final_text.trim()).map_err(|e| {
422:             AgentError::Other(anyhow::anyhow!(
423:                 "collect_typed: failed to deserialize final output: {e}"
424:             ))
425:         })?;
426:         Ok(RunResult {
427:             final_output,
428:             events,
429:             usage,
430:         })
431:     }
432: }
