434: /// Token usage aggregated across all turns of a run.
435: #[derive(Debug, Clone, Copy, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
436: #[non_exhaustive]
437: pub struct TokenUsage {
438:     /// Prompt tokens billed for this run.
439:     pub input_tokens: u64,
440:     /// Completion tokens billed for this run.
441:     pub output_tokens: u64,
442:     /// Tokens served from prompt cache (OpenAI prompt-caching, Anthropic
443:     /// prompt-caching). Counted as `input_tokens` by the provider; this
444:     /// field is informational.
445:     pub cached_input_tokens: u64,
446:     /// Reasoning tokens billed (OpenAI o-series, Anthropic extended
447:     /// thinking).
448:     pub reasoning_tokens: u64,
449:     /// Provider-reported total. May differ from
450:     /// `input_tokens + output_tokens` when the provider excludes cached or
451:     /// reasoning tokens from the billed total. Preserve the provider's
452:     /// value; do not recompute it.
453:     pub total_tokens: u64,
454: }
455: 
456: impl TokenUsage {
457:     /// Add another usage record (per-turn aggregation across a run).
458:     ///
459:     /// `total_tokens` is summed alongside the other fields rather than
460:     /// recomputed from them, preserving each turn's provider-reported total.
461:     pub fn add(&mut self, other: TokenUsage) {
462:         self.input_tokens += other.input_tokens;
463:         self.output_tokens += other.output_tokens;
464:         self.cached_input_tokens += other.cached_input_tokens;
465:         self.reasoning_tokens += other.reasoning_tokens;
466:         self.total_tokens += other.total_tokens;
467:     }
468: }
