470: /// Errors raised by [`Runner`] methods.
471: #[derive(Debug, thiserror::Error)]
472: #[non_exhaustive]
473: pub enum RunError {
474:     /// The underlying agent failed.
475:     #[error("agent failed: {0}")]
476:     Agent(#[from] AgentError),
477: 
478:     /// The runner hit the configured maximum iteration count.
479:     #[error("max iterations reached")]
480:     MaxIterations,
481: 
482:     /// The run was cancelled (e.g. via [`crate::CancellationToken`]).
483:     #[error("cancelled")]
484:     Cancelled,
485: 
486:     /// The run exceeded its configured [`RunConfig::timeout`].
487:     #[error("run timed out")]
488:     Timeout,
489: 
490:     /// Escape hatch.
491:     #[error(transparent)]
492:     Other(#[from] anyhow::Error),
493: }
494: 
495: /// Why a runner's control boundary aborted a run before its natural end.
496: ///
497: /// A runner that wraps the agent's event stream with cancellation and/or a
498: /// deadline observes at most one of these. Whether it actually *wins* — that
499: /// is, overrides the run's own outcome — is decided by [`effective_interrupt`],
500: /// never by the runner on its own.
501: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
502: #[non_exhaustive]
503: pub enum RunInterrupt {
504:     /// The run's [`crate::CancellationToken`] fired.
505:     Cancelled,
506:     /// The run exceeded its [`RunConfig::timeout`].
507:     TimedOut,
508: }
509: 
510: impl RunInterrupt {
511:     /// The [`RunError`] this interrupt surfaces at the runner boundary.
512:     #[must_use]
513:     pub fn run_error(self) -> RunError {
514:         // No wildcard arm: `#[non_exhaustive]` does not apply inside the
515:         // defining crate, so a new variant breaks this match at compile time —
516:         // which is the point.
517:         match self {
518:             Self::Cancelled => RunError::Cancelled,
519:             Self::TimedOut => RunError::Timeout,
520:         }
521:     }
522: 
523:     /// Canonical `error` text for the terminal [`crate::AgentEvent::RunFailed`]
524:     /// a streaming runner synthesizes when this interrupt wins.
525:     ///
526:     /// This is the text alone. Use [`RunInterrupt::terminal_event`] when you
527:     /// need the whole frame — a runner should not assemble one by hand.
528:     #[must_use]
529:     pub fn terminal_message(self) -> &'static str {
530:         match self {
531:             Self::Cancelled => "run cancelled",
532:             Self::TimedOut => "run timed out",
533:         }
534:     }
535: 
536:     /// The terminal [`AgentEvent`] a streaming runner yields when this interrupt
537:     /// wins — see [`effective_interrupt`].
538:     ///
539:     /// Renders through [`RunInterrupt::terminal_message`], so a runner never
540:     /// assembles the frame itself and every runner emits identical bytes for the
541:     /// same interrupt. There is deliberately no second `match self` here: one
542:     /// wildcard-free match per rendering is what makes the `#[non_exhaustive]`
543:     /// compile-break guard worth anything.
544:     #[must_use]
545:     pub fn terminal_event(self) -> AgentEvent {
546:         AgentEvent::RunFailed {
547:             error: self.terminal_message().to_owned(),
548:         }
549:     }
550: }
551: 
552: /// Delegates to [`RunInterrupt::run_error`], which stays the canonical,
553: /// documented name for this mapping.
554: ///
555: /// The `.into()` form is for runner implementations reporting an interrupt that
556: /// won at the control boundary:
557: ///
558: /// ```
559: /// use paigasus_helikon_core::{effective_interrupt, RunError, RunInterrupt};
560: ///

