224: /// The aggregated outcome of a non-streaming [`Runner::run`].
225: ///
226: /// Generic over the structured-output type. The default `T = String`
227: /// makes the common case ergonomic; structured-output callers build
228: /// `RunResult<MyStruct>` via [`RunResult::parse_final`].
229: #[derive(Debug, Default, Clone)]
230: #[non_exhaustive]
231: pub struct RunResult<T = String> {
232:     /// The model's final assistant output, deserialized into `T`. For
233:     /// the default `T = String` this is the literal text.
234:     pub final_output: T,
235:     /// Every [`AgentEvent`] emitted during the run, in order.
236:     pub events: Vec<AgentEvent>,
237:     /// Aggregated token usage across every turn of the run.
238:     pub usage: TokenUsage,
239: }
240: 
241: impl RunResult<String> {
242:     /// Deserialize `final_output` into `T`, producing a typed
243:     /// [`RunResult`].
244:     ///
245:     /// The `T: JsonSchema` bound is the marker that the caller has
246:     /// configured structured output upstream — without it,
247:     /// `parse_final` is just a JSON parse over unstructured text.
248:     pub fn parse_final<T>(self) -> Result<RunResult<T>, serde_json::Error>
249:     where
250:         T: serde::de::DeserializeOwned + schemars::JsonSchema,
251:     {
252:         let final_output = serde_json::from_str::<T>(&self.final_output)?;
253:         Ok(RunResult {
254:             final_output,
255:             events: self.events,
256:             usage: self.usage,
257:         })
258:     }
259: }
