582: /// Apply the runner-boundary precedence rule: **a genuine terminal event beats
583: /// a late cancel/timeout.**
584: ///
585: /// `interrupt` is what the runner's control boundary observed (`None` if it
586: /// never fired). `saw_terminal` is whether the run produced a genuine
587: /// terminal event — see [`crate::AgentEvent::is_terminal`]. Returns the
588: /// interrupt only when it *wins*: when it aborted the run in-flight, before any
589: /// terminal.
590: ///
591: /// This is the executable form of the contract [`Runner::run`] states in prose.
592: /// It exists so that every `Runner` — third-party implementations especially,
593: /// which are its main audience — applies one shared rule instead of re-deriving
594: /// it. The window it closes: a cancel that fires *after* the terminal already
595: /// went out (during a suspending `OnRunComplete` hook, say) must not
596: /// retroactively turn a completed run into a cancelled one.
597: ///
598: /// ```
599: /// use paigasus_helikon_core::{effective_interrupt, RunInterrupt};
600: ///
601: /// // Aborted in-flight: the interrupt wins.
602: /// assert_eq!(
603: ///     effective_interrupt(Some(RunInterrupt::Cancelled), false),
604: ///     Some(RunInterrupt::Cancelled)
605: /// );
606: /// // A terminal already occurred: the interrupt loses.
607: /// assert_eq!(effective_interrupt(Some(RunInterrupt::Cancelled), true), None);
608: /// ```
609: #[must_use]
610: pub fn effective_interrupt(
611:     interrupt: Option<RunInterrupt>,
612:     saw_terminal: bool,
613: ) -> Option<RunInterrupt> {
614:     if saw_terminal {
615:         None
616:     } else {
617:         interrupt
618:     }
619: }
