1: //! `paigasus-helikon-runtime-tokio` — the default ephemeral Tokio runner.
2: //!
3: //! [`TokioRunner`] implements [`paigasus_helikon_core::Runner`] by consuming
4: //! the agent's [`paigasus_helikon_core::AgentEvent`] stream and adding
5: //! run-level control (cancellation, timeout, aggregation) at the boundary. It
6: //! does not own the loop driver — the agent does (see ADR-13).
7: 
8: use std::sync::{Arc, Mutex};
9: use std::time::Duration;
10: 
11: use async_trait::async_trait;
12: use futures_core::stream::BoxStream;
13: use futures_util::stream::StreamExt as _;
14: use paigasus_helikon_core::{
15:     effective_interrupt, Agent, AgentEvent, AgentInput, CancellationToken, RunConfig, RunContext,
16:     RunError, RunInterrupt, RunResult, RunResultStreaming, Runner, Session, SessionRecorder,
17: };
18: 
19: pub mod retry;
20: pub use retry::{RetryPolicy, RetryingModel};
21: 
22: /// Read handle for the interrupt committed by [`controlled`], if any.
23: struct InterruptHandle(Arc<Mutex<Option<RunInterrupt>>>);
24: 
25: impl InterruptHandle {
26:     fn get(&self) -> Option<RunInterrupt> {
27:         *self.0.lock().unwrap()
28:     }
29: }
30: 
31: /// Wrap an agent event stream with cancel/deadline control.
32: ///
33: /// Passes agent events through. On cancellation or deadline it commits the
34: /// reason into the returned handle and ends the stream (dropping the inner
35: /// stream cancels nested in-flight awaits within one poll). The interrupt, if
36: /// any, is committed *before* the terminating `None`, so a caller reading the
37: /// handle after draining never sees a stale value. A run that ends naturally
38: /// commits nothing and the handle stays `None`.
39: fn controlled(
40:     mut stream: BoxStream<'static, AgentEvent>,
41:     cancel: CancellationToken,
42:     timeout: Option<Duration>,
43: ) -> (BoxStream<'static, AgentEvent>, InterruptHandle) {
44:     let cell = Arc::new(Mutex::new(None));
45:     let handle = InterruptHandle(Arc::clone(&cell));
46:     let out = async_stream::stream! {
47:         let sleep = async move {
48:             match timeout {
49:                 Some(d) => tokio::time::sleep(d).await,
50:                 None => std::future::pending::<()>().await,
51:             }
52:         };
53:         tokio::pin!(sleep);
54:         loop {
55:             tokio::select! {
56:                 biased;
57:                 maybe_ev = stream.next() => {
58:                     match maybe_ev {
59:                         Some(ev) => yield ev,
60:                         None => break, // inner stream done => no interrupt
61:                     }
62:                 }
63:                 () = cancel.cancelled() => {
64:                     *cell.lock().unwrap() = Some(RunInterrupt::Cancelled);
65:                     break;
66:                 }
67:                 () = &mut sleep => {
68:                     *cell.lock().unwrap() = Some(RunInterrupt::TimedOut);
69:                     break;
70:                 }
71:             }
72:         }
73:     };
74:     (Box::pin(out), handle)
75: }
76: 
77: /// Snapshot the session into the merged input and seed a recorder with the
78: /// run's new-turn messages. A read failure is a hard error: the run cannot
79: /// faithfully resume from an unreadable session, so it fails before the agent
80: /// starts. (The write side, by contrast, is best-effort — see `finalize`.)
81: async fn load_and_record(
82:     session: &Arc<dyn Session>,
83:     agent_name: &str,
84:     input: AgentInput,
85: ) -> Result<(AgentInput, Arc<Mutex<SessionRecorder>>), RunError> {
86:     let snapshot = session
87:         .snapshot()
88:         .await
89:         .map_err(|e| RunError::Other(anyhow::Error::new(e)))?;
90:     let mut recorder = SessionRecorder::new(agent_name);
91:     recorder.record_input(&input.messages);
92: 
93:     let mut merged = AgentInput::new();
94:     merged.messages = snapshot.messages;
95:     merged.messages.extend(input.messages);
96:     Ok((merged, Arc::new(Mutex::new(recorder))))
97: }
98: 
99: /// Post-run finalization: drain the recorder and append the run's events.
100: /// Persistence is best-effort — an append error is logged, never propagated, so
101: /// the run's outcome (Ok / Cancelled / Timeout / Agent error) is unchanged.
102: async fn finalize(session: &Arc<dyn Session>, recorder: &Arc<Mutex<SessionRecorder>>) {
103:     let events = recorder
104:         .lock()
105:         .expect("session recorder mutex poisoned")
106:         .drain();
107:     if let Err(e) = session.append(&events).await {
108:         tracing::warn!(
109:             target: "paigasus::runtime_tokio::runner",
110:             error = %e,
111:             "session persistence failed during finalize; run outcome unaffected"
112:         );
113:     }
114: }
115: 
116: /// The default ephemeral execution backend. Stateless.
117: #[derive(Debug, Clone, Copy, Default)]
118: pub struct TokioRunner;
119: 
120: #[async_trait]
121: impl<Ctx> Runner<Ctx> for TokioRunner
122: where
123:     Ctx: Send + Sync + 'static,
124: {
125:     async fn run(
126:         &self,
127:         agent: &(dyn Agent<Ctx> + '_),
128:         ctx: RunContext<Ctx>,
129:         input: AgentInput,
130:         config: RunConfig,
131:     ) -> Result<RunResult, RunError> {
132:         let timeout = config.timeout;
133:         let ctx = ctx.with_run_config(config);
134:         let cancel = ctx.cancel().clone();
135:         let session = ctx.session().clone();
136:         let failure = ctx.failure_handle();
137: 
138:         // Load persisted history and seed the recorder with the new turn.
139:         let (merged, recorder) = load_and_record(&session, agent.name(), input).await?;
140: 
141:         let stream = agent.run(ctx, merged).await?;
142:         let (controlled_stream, interrupt) = controlled(stream, cancel, timeout);
143:         let rec_inspect = Arc::clone(&recorder);
144:         let recorded = controlled_stream
145:             .inspect(move |ev| {
146:                 rec_inspect
147:                     .lock()
148:                     .expect("session recorder mutex poisoned")
149:                     .observe(ev)
150:             })
151:             .boxed();
152:         // Do NOT `?`-short-circuit before finalize: agent failures surface as
153:         // collect()=Err, and finalize must still run.
154:         let collected = RunResultStreaming::with_failure(recorded, failure)
155:             .collect()
156:             .await;
157:         finalize(&session, &recorder).await;
158: 
159:         // A genuine terminal event (RunCompleted/RunFailed) is the run's true
160:         // outcome; a cancel/timeout overrides ONLY when no terminal was
161:         // observed — i.e. it actually aborted the run in-flight. The rule
162:         // itself lives in core as `effective_interrupt` so every runner applies
163:         // one definition (SMA-422); see `Runner::run`'s docs for the contract
164:         // and SMA-421 for the bug it closes.
165:         let saw_terminal = collected
166:             .as_ref()
167:             .map(|r| r.events.iter().any(AgentEvent::is_terminal))
168:             .unwrap_or(true); // Err(_) from collect() ⇔ a RunFailed was observed
169: 
170:         match effective_interrupt(interrupt.get(), saw_terminal).map(RunInterrupt::run_error) {
171:             Some(err) => Err(err),
172:             None => collected,
173:         }
174:     }
175: 
176:     async fn run_streamed(
177:         &self,
178:         agent: &(dyn Agent<Ctx> + '_),
179:         ctx: RunContext<Ctx>,
180:         input: AgentInput,
181:         config: RunConfig,
182:     ) -> Result<RunResultStreaming, RunError> {
183:         let timeout = config.timeout;
184:         let ctx = ctx.with_run_config(config);
185:         let cancel = ctx.cancel().clone();
186:         let session = ctx.session().clone();
187:         let failure = ctx.failure_handle();
188: 
189:         let (merged, recorder) = load_and_record(&session, agent.name(), input).await?;
190: 
191:         let stream = agent.run(ctx, merged).await?;
192:         let (controlled_stream, interrupt) = controlled(stream, cancel, timeout);
193:         let rec_inspect = Arc::clone(&recorder);
194:         let mut recorded = controlled_stream
195:             .inspect(move |ev| {
196:                 rec_inspect
197:                     .lock()
198:                     .expect("session recorder mutex poisoned")
199:                     .observe(ev)
200:             })
201:             .boxed();
202: 
203:         let out = async_stream::stream! {
204:             let mut saw_terminal = false;
205:             let mut finalized = false;
206:             while let Some(ev) = recorded.next().await {
207:                 // Finalize BEFORE exposing a terminal event: a consumer may stop
208:                 // polling (and drop the stream) the moment it sees the terminal,
209:                 // so anything after the `yield` could never run.
210:                 if AgentEvent::is_terminal(&ev) {
211:                     if !finalized {
212:                         finalize(&session, &recorder).await;
213:                         finalized = true;
214:                     }
215:                     saw_terminal = true;
216:                 }
217:                 yield ev;
218:             }
219:             // Synthesize a terminal ONLY when the run aborted in-flight (no real
220:             // terminal was ever yielded). Reaching here with `!saw_terminal`
221:             // means the loop never finalized, so finalize directly. A late
222:             // cancel/timeout that fired AFTER a real terminal — e.g. during a
223:             // suspending OnRunComplete hook — must NOT emit a second, synthetic
224:             // terminal; `effective_interrupt` is what decides that (SMA-422,
225:             // closing SMA-421). Note the natural-completion case (no terminal,
226:             // no interrupt) deliberately does not finalize here — pre-existing
227:             // behaviour, preserved.
228:             if let Some(i) = effective_interrupt(interrupt.get(), saw_terminal) {
229:                 finalize(&session, &recorder).await;
230:                 yield i.terminal_event();
231:             }
232:         };
233:         Ok(RunResultStreaming::with_failure(Box::pin(out), failure))
234:     }
235: }
