5: //! run-level control (cancellation, timeout, aggregation) at the boundary. It
6: //! does not own the loop driver — the agent does (see ADR-13).
7: 
8: use std::sync::{Arc, Mutex};
9: use std::time::Duration;
10: 
11: use async_trait::async_trait;
12: use futures_core::stream::BoxStream;
13: use futures_util::stream::StreamExt as _;
14: use paigasus_helikon_core::{
15:     effective_interrupt, Agent, AgentEvent, AgentInput, CancellationToken, RunConfig, RunContext,
16:     RunError, RunInterrupt, RunResult, RunResultStreaming, Runner, Session, SessionRecorder,
17: };
18: 
19: pub mod retry;
20: pub use retry::{RetryPolicy, RetryingModel};
21: 
22: /// Read handle for the interrupt committed by [`controlled`], if any.
23: struct InterruptHandle(Arc<Mutex<Option<RunInterrupt>>>);
24: 
25: impl InterruptHandle {
26:     fn get(&self) -> Option<RunInterrupt> {
27:         *self.0.lock().unwrap()
28:     }
29: }
30: 
31: /// Wrap an agent event stream with cancel/deadline control.
32: ///
33: /// Passes agent events through. On cancellation or deadline it commits the
34: /// reason into the returned handle and ends the stream (dropping the inner
35: /// stream cancels nested in-flight awaits within one poll). The interrupt, if
36: /// any, is committed *before* the terminating `None`, so a caller reading the
37: /// handle after draining never sees a stale value. A run that ends naturally
38: /// commits nothing and the handle stays `None`.
39: fn controlled(
40:     mut stream: BoxStream<'static, AgentEvent>,
41:     cancel: CancellationToken,
42:     timeout: Option<Duration>,
43: ) -> (BoxStream<'static, AgentEvent>, InterruptHandle) {
44:     let cell = Arc::new(Mutex::new(None));
45:     let handle = InterruptHandle(Arc::clone(&cell));
46:     let out = async_stream::stream! {
47:         let sleep = async move {
48:             match timeout {
49:                 Some(d) => tokio::time::sleep(d).await,
50:                 None => std::future::pending::<()>().await,
51:             }
52:         };
53:         tokio::pin!(sleep);
54:         loop {
55:             tokio::select! {
56:                 biased;
57:                 maybe_ev = stream.next() => {
58:                     match maybe_ev {
59:                         Some(ev) => yield ev,
60:                         None => break, // inner stream done => no interrupt
61:                     }
62:                 }
63:                 () = cancel.cancelled() => {
64:                     *cell.lock().unwrap() = Some(RunInterrupt::Cancelled);
65:                     break;
66:                 }
67:                 () = &mut sleep => {
68:                     *cell.lock().unwrap() = Some(RunInterrupt::TimedOut);
69:                     break;
70:                 }
71:             }
72:         }
73:     };
74:     (Box::pin(out), handle)
75: }
76: 
77: /// Snapshot the session into the merged input and seed a recorder with the
78: /// run's new-turn messages. A read failure is a hard error: the run cannot
79: /// faithfully resume from an unreadable session, so it fails before the agent
80: /// starts. (The write side, by contrast, is best-effort — see `finalize`.)
81: async fn load_and_record(
82:     session: &Arc<dyn Session>,
83:     agent_name: &str,
84:     input: AgentInput,
85: ) -> Result<(AgentInput, Arc<Mutex<SessionRecorder>>), RunError> {
86:     let snapshot = session
87:         .snapshot()
88:         .await
89:         .map_err(|e| RunError::Other(anyhow::Error::new(e)))?;
90:     let mut recorder = SessionRecorder::new(agent_name);
91:     recorder.record_input(&input.messages);
92: 
93:     let mut merged = AgentInput::new();
94:     merged.messages = snapshot.messages;
95:     merged.messages.extend(input.messages);
96:     Ok((merged, Arc::new(Mutex::new(recorder))))
97: }
98: 
99: /// Post-run finalization: drain the recorder and append the run's events.
100: /// Persistence is best-effort — an append error is logged, never propagated, so
101: /// the run's outcome (Ok / Cancelled / Timeout / Agent error) is unchanged.
102: async fn finalize(session: &Arc<dyn Session>, recorder: &Arc<Mutex<SessionRecorder>>) {
103:     let events = recorder
104:         .lock()
105:         .expect("session recorder mutex poisoned")
106:         .drain();
107:     if let Err(e) = session.append(&events).await {
108:         tracing::warn!(
109:             target: "paigasus::runtime_tokio::runner",
110:             error = %e,
111:             "session persistence failed during finalize; run outcome unaffected"
112:         );
113:     }
114: }
