116: /// The default ephemeral execution backend. Stateless.
117: #[derive(Debug, Clone, Copy, Default)]
118: pub struct TokioRunner;
119: 
120: #[async_trait]
121: impl<Ctx> Runner<Ctx> for TokioRunner
122: where
123:     Ctx: Send + Sync + 'static,
124: {
125:     async fn run(
126:         &self,
127:         agent: &(dyn Agent<Ctx> + '_),
128:         ctx: RunContext<Ctx>,
129:         input: AgentInput,
130:         config: RunConfig,
131:     ) -> Result<RunResult, RunError> {
132:         let timeout = config.timeout;
133:         let ctx = ctx.with_run_config(config);
134:         let cancel = ctx.cancel().clone();
135:         let session = ctx.session().clone();
136:         let failure = ctx.failure_handle();
137: 
138:         // Load persisted history and seed the recorder with the new turn.
139:         let (merged, recorder) = load_and_record(&session, agent.name(), input).await?;
140: 
141:         let stream = agent.run(ctx, merged).await?;
142:         let (controlled_stream, interrupt) = controlled(stream, cancel, timeout);
143:         let rec_inspect = Arc::clone(&recorder);
144:         let recorded = controlled_stream
145:             .inspect(move |ev| {
146:                 rec_inspect
147:                     .lock()
148:                     .expect("session recorder mutex poisoned")
149:                     .observe(ev)
150:             })
151:             .boxed();
152:         // Do NOT `?`-short-circuit before finalize: agent failures surface as
153:         // collect()=Err, and finalize must still run.
154:         let collected = RunResultStreaming::with_failure(recorded, failure)
155:             .collect()
156:             .await;
157:         finalize(&session, &recorder).await;
158: 
159:         // A genuine terminal event (RunCompleted/RunFailed) is the run's true
160:         // outcome; a cancel/timeout overrides ONLY when no terminal was
161:         // observed — i.e. it actually aborted the run in-flight. The rule
162:         // itself lives in core as `effective_interrupt` so every runner applies
163:         // one definition (SMA-422); see `Runner::run`'s docs for the contract
164:         // and SMA-421 for the bug it closes.
165:         let saw_terminal = collected
166:             .as_ref()
167:             .map(|r| r.events.iter().any(AgentEvent::is_terminal))
168:             .unwrap_or(true); // Err(_) from collect() ⇔ a RunFailed was observed
169: 
170:         match effective_interrupt(interrupt.get(), saw_terminal).map(RunInterrupt::run_error) {
171:             Some(err) => Err(err),
172:             None => collected,
173:         }
174:     }
175: 
176:     async fn run_streamed(
177:         &self,
178:         agent: &(dyn Agent<Ctx> + '_),
179:         ctx: RunContext<Ctx>,
180:         input: AgentInput,
181:         config: RunConfig,
182:     ) -> Result<RunResultStreaming, RunError> {
183:         let timeout = config.timeout;
184:         let ctx = ctx.with_run_config(config);
185:         let cancel = ctx.cancel().clone();
186:         let session = ctx.session().clone();
187:         let failure = ctx.failure_handle();
188: 
189:         let (merged, recorder) = load_and_record(&session, agent.name(), input).await?;
190: 
191:         let stream = agent.run(ctx, merged).await?;
192:         let (controlled_stream, interrupt) = controlled(stream, cancel, timeout);
193:         let rec_inspect = Arc::clone(&recorder);
194:         let mut recorded = controlled_stream
195:             .inspect(move |ev| {
196:                 rec_inspect
197:                     .lock()
198:                     .expect("session recorder mutex poisoned")
199:                     .observe(ev)
200:             })
201:             .boxed();
202: 
203:         let out = async_stream::stream! {
204:             let mut saw_terminal = false;
205:             let mut finalized = false;
206:             while let Some(ev) = recorded.next().await {
207:                 // Finalize BEFORE exposing a terminal event: a consumer may stop
208:                 // polling (and drop the stream) the moment it sees the terminal,
209:                 // so anything after the `yield` could never run.
210:                 if AgentEvent::is_terminal(&ev) {
211:                     if !finalized {
212:                         finalize(&session, &recorder).await;
213:                         finalized = true;
214:                     }
215:                     saw_terminal = true;
216:                 }
217:                 yield ev;
218:             }
219:             // Synthesize a terminal ONLY when the run aborted in-flight (no real
220:             // terminal was ever yielded). Reaching here with `!saw_terminal`
221:             // means the loop never finalized, so finalize directly. A late
222:             // cancel/timeout that fired AFTER a real terminal — e.g. during a
223:             // suspending OnRunComplete hook — must NOT emit a second, synthetic
224:             // terminal; `effective_interrupt` is what decides that (SMA-422,
225:             // closing SMA-421). Note the natural-completion case (no terminal,
226:             // no interrupt) deliberately does not finalize here — pre-existing
227:             // behaviour, preserved.
228:             if let Some(i) = effective_interrupt(interrupt.get(), saw_terminal) {
229:                 finalize(&session, &recorder).await;
230:                 yield i.terminal_event();
231:             }
232:         };
233:         Ok(RunResultStreaming::with_failure(Box::pin(out), failure))
234:     }
235: }
