402: /// Accumulates one run's semantic items as [`SessionEvent`]s for the runner to
403: /// persist at run exit.
404: ///
405: /// The runner pre-seeds the recorder with the run's `AgentInput` messages (the
406: /// new turn — which the agent does not re-emit on its event stream), then feeds
407: /// it every [`crate::AgentEvent`] as the stream flows. [`SessionRecorder::drain`]
408: /// returns the accumulated log, synthesizing a [`SessionEvent::ToolReturned`]
409: /// for any tool call left without a result (a run interrupted mid-tool) so the
410: /// log always [`project`]s to a provider-valid conversation.
411: #[derive(Debug)]
412: pub struct SessionRecorder {
413:     events: Vec<SessionEvent>,
414:     current_agent: String,
415: }
416: 
417: impl SessionRecorder {
418:     /// Create a recorder seeded with the root agent's name. Used to attribute
419:     /// assistant messages whose [`Item::AssistantMessage`] `agent` is `None`,
420:     /// before any `RunStarted`/`AgentUpdated` updates the tracked agent.
421:     pub fn new(root_agent: impl Into<String>) -> Self {
422:         Self {
423:             events: Vec::new(),
424:             current_agent: root_agent.into(),
425:         }
426:     }
427: 
428:     /// Record the run's input messages (the new turn). The agent never re-emits
429:     /// these on its event stream, so the runner records them directly.
430:     /// [`Item::System`] has no [`SessionEvent`] equivalent and is skipped.
431:     pub fn record_input(&mut self, messages: &[Item]) {
432:         for item in messages {
433:             match item {
434:                 Item::UserMessage { content } => {
435:                     self.events
436:                         .push(SessionEvent::user_message(content.clone()));
437:                 }
438:                 Item::AssistantMessage { content, agent } => {
439:                     let name = agent.clone().unwrap_or_else(|| self.current_agent.clone());
440:                     self.events
441:                         .push(SessionEvent::assistant_message(content.clone(), name));
442:                 }
443:                 Item::ToolCall {
444:                     call_id,
445:                     name,
446:                     args,
447:                 } => {
448:                     self.events.push(SessionEvent::tool_called(
449:                         call_id.clone(),
450:                         name.clone(),
451:                         args.clone(),
452:                     ));
453:                 }
454:                 Item::ToolResult { call_id, content } => {
455:                     self.events.push(SessionEvent::tool_returned(
456:                         call_id.clone(),
457:                         content.clone(),
458:                     ));
459:                 }
460:                 Item::System { .. } => {
461:                     tracing::debug!(
462:                         target: "paigasus::core::session",
463:                         "SessionRecorder: skipping Item::System in input (no SessionEvent variant)"
464:                     );
465:                 }
466:             }
467:         }
468:     }
469: 
470:     /// Observe one [`crate::AgentEvent`] from the run's stream: record the
471:     /// semantic items (assistant messages, tool calls, tool results, handoffs)
472:     /// and track the active agent from `RunStarted` / `AgentUpdated`.
473:     pub fn observe(&mut self, event: &AgentEvent) {
474:         match event {
475:             AgentEvent::RunStarted { agent } | AgentEvent::AgentUpdated { agent } => {
476:                 self.current_agent = agent.clone();
477:             }
478:             AgentEvent::MessageOutput {
479:                 item: Item::AssistantMessage { content, agent },
480:             } => {
481:                 let name = agent.clone().unwrap_or_else(|| self.current_agent.clone());
482:                 self.events
483:                     .push(SessionEvent::assistant_message(content.clone(), name));
484:             }
485:             AgentEvent::ToolCallItem {
486:                 item:
487:                     Item::ToolCall {
488:                         call_id,
489:                         name,
490:                         args,
491:                     },
492:             } => {
493:                 self.events.push(SessionEvent::tool_called(
494:                     call_id.clone(),
495:                     name.clone(),
496:                     args.clone(),
497:                 ));
498:             }
499:             AgentEvent::ToolOutputItem {
500:                 item: Item::ToolResult { call_id, content },
501:             } => {
502:                 self.events.push(SessionEvent::tool_returned(
503:                     call_id.clone(),
504:                     content.clone(),
505:                 ));
506:             }
507:             AgentEvent::HandoffItem { from, to } => {
508:                 self.events
509:                     .push(SessionEvent::handoff_occurred(from.clone(), to.clone()));
510:             }
511:             _ => {}
512:         }
513:     }
514: 
515:     /// Drain the accumulated events, appending a synthesized
516:     /// [`SessionEvent::ToolReturned`] for every [`SessionEvent::ToolCalled`]
517:     /// left without a matching result (a run cancelled/timed out mid-tool).
518:     /// The returned log always [`project`]s to a provider-valid conversation.
519:     pub fn drain(&mut self) -> Vec<SessionEvent> {
520:         let returned: std::collections::HashSet<String> = self
521:             .events
522:             .iter()
523:             .filter_map(|e| match e {
524:                 SessionEvent::ToolReturned { call_id, .. } => Some(call_id.clone()),
525:                 _ => None,
526:             })
527:             .collect();
528:         let mut synthesized = Vec::new();
529:         for e in &self.events {
530:             if let SessionEvent::ToolCalled { call_id, .. } = e {
531:                 if !returned.contains(call_id) {
532:                     synthesized.push(SessionEvent::tool_returned(
533:                         call_id.clone(),
534:                         vec![ContentPart::Text {
535:                             text: "tool call did not complete (run cancelled/timed out)".to_owned(),
536:                         }],
537:                     ));
538:                 }
539:             }
540:         }
541:         let mut out = std::mem::take(&mut self.events);
542:         out.extend(synthesized);
543:         out
544:     }
545: }
546: 
547: /// Monotonic position in a [`Session`]'s append-only log.
548: #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
549: pub struct SequenceId(pub u64);
