552: /// conversation state. The `messages` field is the canonical view a
553: /// session emits.
554: #[derive(Debug, Clone, Default, Serialize, Deserialize)]
555: #[non_exhaustive]
556: pub struct ConversationSnapshot {
557:     /// Canonical message list, in conversational order.
558:     pub messages: Vec<Item>,
559: }
