561: /// Errors raised by [`Session`] methods.
562: #[derive(Debug, thiserror::Error)]
563: #[non_exhaustive]
564: pub enum SessionError {
565:     /// Backend unreachable (database down, file locked, …).
566:     #[error("session backend unavailable")]
567:     Unavailable,
568: 
569:     /// A backend-specific error, type-erased so core stays free of any
570:     /// particular backend dependency. The `'static` bound is required for
571:     /// `<dyn Error>::downcast_ref` to work; callers who care about
572:     /// the underlying type can do `err.downcast_ref::<sqlx::Error>()`.
573:     #[error(transparent)]
574:     Backend(Box<dyn std::error::Error + Send + Sync + 'static>),
575: 
576:     /// Escape hatch.
577:     #[error(transparent)]
578:     Other(#[from] anyhow::Error),
579: }
580: 
581: impl SessionError {
582:     /// Wrap a backend-specific error as [`SessionError::Backend`].
583:     ///
584:     /// Saves the
585:     /// `.map_err(|e| SessionError::Backend(Box::new(e)))` boilerplate at
586:     /// every query call site — use as `.map_err(SessionError::backend)`.
587:     pub fn backend<E>(e: E) -> Self
588:     where
589:         E: std::error::Error + Send + Sync + 'static,
590:     {
591:         Self::Backend(Box::new(e))
592:     }
593: }
