1: //! [`AgentAsTool`] — expose any [`crate::Agent`] as a [`crate::Tool`].
2: //!
3: //! The parent agent calls the wrapped agent like any tool, gets its
4: //! `final_output` back as a [`crate::ToolOutput`], and keeps reasoning. The
5: //! sub-run is **isolated**: a fresh in-memory session and empty hooks, so its
6: //! internal turns never touch the parent's session log.
7: 
8: use std::sync::Arc;
9: 
10: use async_trait::async_trait;
11: use serde_json::Value;
12: 
13: use crate::{
14:     Agent, AgentInput, HookRegistry, MemorySession, RunContext, RunError, RunResultStreaming, Tool,
15:     ToolContext, ToolError, ToolOutput,
16: };
17: 
18: /// Adapter exposing an [`Agent`] as a [`Tool`].
19: ///
20: /// The sub-run is **isolated**: a fresh in-memory session and empty hooks, so
21: /// its internal turns never touch the parent's session log. The wrapped agent
22: /// runs under its **own** [`crate::RunConfig`] — the parent's `run_config`
23: /// (`max_turns`, `timeout`, `max_agent_depth`) does **not** cross this boundary.
24: /// Only the nesting depth crosses: the parent-side guard caps entry at the
25: /// parent's `max_agent_depth`, and the wrapped agent's own config bounds any
26: /// further nesting it performs, so recursion stays bounded along the whole chain.
27: pub struct AgentAsTool<Ctx> {
28:     agent: Arc<dyn Agent<Ctx>>,
29:     name: String,
30:     description: String,
31:     schema: Value,
32: }
33: 
34: impl<Ctx> AgentAsTool<Ctx>
35: where
36:     Ctx: Send + Sync + 'static,
37: {
38:     /// Wrap an owned agent. The tool name and description default to the
39:     /// agent's own; the argument schema is a single string field `input`.
40:     pub fn new(agent: impl Agent<Ctx> + 'static) -> Self {
41:         Self::shared(Arc::new(agent))
42:     }
43: 
44:     /// Wrap a pre-wrapped agent.
45:     pub fn shared(agent: Arc<dyn Agent<Ctx>>) -> Self {
46:         let name = agent.name().to_owned();
47:         let description = agent.description().to_owned();
48:         Self {
49:             agent,
50:             name,
51:             description,
52:             schema: serde_json::json!({
53:                 "type": "object",
54:                 "properties": {
55:                     "input": {
56:                         "type": "string",
57:                         "description": "The request to pass to the wrapped agent."
58:                     }
59:                 },
60:                 "required": ["input"],
61:                 "additionalProperties": false
62:             }),
63:         }
64:     }
65: 
66:     /// Override the tool name (default: the agent's name).
67:     pub fn with_name(mut self, name: impl Into<String>) -> Self {
68:         self.name = name.into();
69:         self
70:     }
71: 
72:     /// Override the tool description (default: the agent's description).
73:     pub fn with_description(mut self, description: impl Into<String>) -> Self {
74:         self.description = description.into();
75:         self
76:     }
77: }
78: 
79: #[async_trait]
80: impl<Ctx> Tool<Ctx> for AgentAsTool<Ctx>
81: where
82:     Ctx: Send + Sync + 'static,
83: {
84:     fn name(&self) -> &str {
85:         &self.name
86:     }
87:     fn description(&self) -> &str {
88:         &self.description
89:     }
90:     fn schema(&self) -> &Value {
91:         &self.schema
92:     }
93: 
94:     async fn invoke(&self, ctx: &ToolContext<Ctx>, args: Value) -> Result<ToolOutput, ToolError> {
95:         let input_text =
96:             args.get("input")
97:                 .and_then(|v| v.as_str())
98:                 .ok_or_else(|| ToolError::InvalidArgs {
99:                     schema_errors: vec!["expected a string field `input`".to_owned()],
100:                 })?;
101: 
102:         // Bound nesting with the same counter the handoff path uses.
103:         let depth = ctx.agent_depth();
104:         let max = ctx.max_agent_depth();
105:         if depth + 1 > max {
106:             return Err(ToolError::Other(anyhow::Error::from(
107:                 crate::AgentError::MaxAgentDepthExceeded {
108:                     depth: depth + 1,
109:                     max,
110:                 },
111:             )));
112:         }
113: 
114:         // Isolated sub-context: fresh session + empty hooks; inherit user_ctx,
115:         // tracer, and the child cancel token; stamp the incremented depth.
116:         // Security-critical: the parent's permission config (mode, policy,
117:         // deny rules, allow rules, approval handler, guard rules, and the
118:         // redaction config) MUST cross into the sub-run so that a
119:         // `Plan`/`Bypass`/`DontAsk`/policy decision applies to the wrapped
120:         // agent's tools, and so that custom guard rules and extra-secret
121:         // redaction remain in force. Dropping the allow rules is a fail-closed
122:         // propagation bug: under `DontAsk` an unmatched call is denied, so a
123:         // sub-run that lost them would silently deny everything.
124:         let mut sub_ctx = RunContext::new(
125:             Arc::clone(ctx.user_ctx()),
126:             Arc::new(MemorySession::new()),
127:             HookRegistry::new(),
128:             ctx.tracer().clone(),
129:             ctx.cancel().clone(),
130:         )
131:         .with_agent_depth(depth + 1)
132:         .with_permission_mode(ctx.permission_mode())
133:         .with_deny_rules(ctx.deny_rules.clone())
134:         .with_allow_rules(ctx.allow_rules.clone())
135:         .with_guard_rules(ctx.guard_rules.clone())
136:         .with_extra_secrets(ctx.extra_secrets.clone());
137:         if let Some(p) = ctx.permission_policy.clone() {
138:             sub_ctx = sub_ctx.with_permission_policy(p);
139:         }
140:         if let Some(h) = ctx.approval_handler.clone() {
141:             sub_ctx = sub_ctx.with_approval_handler(h);
142:         }
143:         if !ctx.default_guards {
144:             sub_ctx = sub_ctx.without_default_guards();
145:         }
146:         if !ctx.redact_output {
147:             sub_ctx = sub_ctx.without_output_redaction();
148:         }
149: 
150:         let failure = sub_ctx.failure_handle();
151:         let stream = self
152:             .agent
153:             .run(sub_ctx, AgentInput::from_user_text(input_text))
154:             .await
155:             .map_err(|e| ToolError::Other(anyhow::Error::from(e)))?;
156: 
157:         // Collect without `?` so OnSubagentStop fires whether the sub-run
158:         // succeeded or failed (matching the workflow / handoff paths).
159:         let result = RunResultStreaming::with_failure(stream, failure)
160:             .collect()
161:             .await;
162: 
163:         // Fire OnSubagentStop against the parent's run-level hooks. The sub-run
164:         // used an isolated (empty) registry; this fires the PARENT's hooks so a
165:         // run-level OnSubagentStop consumer sees the agent-as-tool sub-run stop.
166:         // `Hook::on_event` needs a `&RunContext`, which a tool doesn't have (only
167:         // a `ToolContext`), so we build a fire-only context. It shares the
168:         // parent's run-scoped `state` (plus user_ctx/tracer/cancel) so
169:         // state-reading hooks see the real run; `session`/`run_config` stay
170:         // defaults — the full parent `RunContext` doesn't cross the tool boundary.
171:         let fire_ctx = RunContext::new(
172:             Arc::clone(ctx.user_ctx()),
173:             Arc::new(MemorySession::new()),
174:             HookRegistry::new(),
175:             ctx.tracer().clone(),
176:             ctx.cancel().clone(),
177:         )
178:         .with_state(ctx.state().clone());
179:         for hook in ctx.hooks.iter() {
180:             let _ = hook
181:                 .on_event(
182:                     &fire_ctx,
183:                     &crate::HookEvent::OnSubagentStop {
184:                         agent: self.agent.name().to_owned(),
185:                     },
186:                 )
187:                 .await;
188:         }
189: 
190:         let result = result.map_err(|e| match e {
191:             RunError::Agent(a) => ToolError::Other(anyhow::Error::from(a)),
192:             other => ToolError::Other(anyhow::Error::from(other)),
193:         })?;
194: 
195:         Ok(ToolOutput::new(Value::String(result.final_output)))
196:     }
197: }

